const P=$('Store Prospect Status').first().json.rows;
const D=$('Store Follow-up Drafts').first().json.rows;
const L=$input.all().map(i=>i.json);
const n=r=>Number(r['#']||r['Prospect #']);
const text=v=>String(v??'').trim();
const em=v=>text(v).toLowerCase();
const pm=new Map(P.map(x=>[n(x),x])),dm=new Map(D.map(x=>[n(x),x]));
const out=[];
for(const l of L){
 const id=n(l),p=pm.get(id),d=dm.get(id),issues=[],body=text(d?.['Follow-up Template']);
 if(!p||!d)issues.push('Prospect or template missing');
 if(!l['Original Gmail Message ID']||!l['Original Thread ID'])issues.push('No verified originating Gmail ID');
 if(p?.Status!=='Sent'||p?.['Reply Date']||p?.['Follow-up Date'])issues.push('Prospect already replied or followed up');
 if(text(l['Send Status'])!=='PENDING'||text(l['Follow-up Gmail ID'])||text(l['Follow-up Sent ET']))issues.push('Follow-up already logged');
 if(text(l['Review Status'])!=='READY')issues.push('Review disposition held');
 if(em(l.Recipient)!==em(p?.['Public Email'])||em(l.Recipient)!==em(d?.['Send To']))issues.push('Address differs from initial outreach');
 if(!body||!body.toLowerCase().includes('unsubscribe'))issues.push('Template missing/invalid');
 if([24,25,29,31].includes(id))issues.push('Explicit contact exception');
 out.push({json:{prospect_id:id,business:l.Business,to:l.Recipient,original_gmail_message_id:l['Original Gmail Message ID'],original_thread_id:l['Original Thread ID'],followup_body:body,eligibility:issues.length?'HOLD':'READY_PENDING_LIVE_GMAIL_THREAD_CHECK_AND_APPROVAL',issues,approved:false,sent:false}});
}
if(out.length!==16)throw Error('Expected exactly 16 follow-up rows, got '+out.length);
return out;
